CREATE TABLE IF NOT EXISTS Settings(Key TEXT PRIMARY KEY, Value TEXT);
CREATE TABLE IF NOT EXISTS Clients(Id INTEGER PRIMARY KEY AUTOINCREMENT,Name TEXT,CompanyName TEXT,ContactPerson TEXT,Phone TEXT,WhatsApp TEXT,Email TEXT,Website TEXT,SocialMediaLinks TEXT,Address TEXT,Notes TEXT,Status TEXT);
CREATE TABLE IF NOT EXISTS Leads(Id INTEGER PRIMARY KEY AUTOINCREMENT,Name TEXT,Source TEXT,Stage TEXT,EstimatedValue REAL,NextFollowUpDate TEXT,Notes TEXT);
CREATE TABLE IF NOT EXISTS Projects(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,Title TEXT,Description TEXT,ProjectType TEXT,StartDate TEXT,Deadline TEXT,Status TEXT,Budget REAL,InternalNotes TEXT,AttachmentPaths TEXT);
CREATE TABLE IF NOT EXISTS Tasks(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,ProjectId INTEGER,Title TEXT,Description TEXT,Priority TEXT,Status TEXT,DueDate TEXT,AssignedPerson TEXT,ChecklistJson TEXT);
CREATE TABLE IF NOT EXISTS CalendarEvents(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,ProjectId INTEGER,Title TEXT,EventDate TEXT,EventType TEXT,Notes TEXT);
CREATE TABLE IF NOT EXISTS Proposals(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,LeadId INTEGER,Title TEXT,ServicesIncluded TEXT,Description TEXT,Price REAL,Discount REAL,TotalValue REAL,Status TEXT);
CREATE TABLE IF NOT EXISTS Contracts(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,ProjectId INTEGER,Title TEXT,StartDate TEXT,EndDate TEXT,MonthlyValue REAL,Status TEXT,RenewalReminderDate TEXT,FilePath TEXT);
CREATE TABLE IF NOT EXISTS FinancialEntries(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,ProjectId INTEGER,Type TEXT,Description TEXT,Amount REAL,PaymentStatus TEXT,DueDate TEXT,PaymentMethod TEXT,RecurringMonthly INTEGER);
CREATE TABLE IF NOT EXISTS SocialMediaPosts(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,Platform TEXT,PostTitle TEXT,Caption TEXT,Hashtags TEXT,PostStatus TEXT,ScheduledDate TEXT,ApprovalStatus TEXT,Notes TEXT);
CREATE TABLE IF NOT EXISTS WebsiteMaintenance(Id INTEGER PRIMARY KEY AUTOINCREMENT,ClientId INTEGER,Domain TEXT,HostingProvider TEXT,CmsUsed TEXT,WordpressLoginUrl TEXT,RenewalDate TEXT,SslExpirationDate TEXT,MaintenanceNotes TEXT,BackupDate TEXT,UpdateNotes TEXT);
